+fn aligned(deg: [f64; 3], vise: bool) -> (World, History, Aabb) {
+    let world = new_world();
+    let mut h = History::default();
+    h.execute(&world, ImportModel::from_mesh("part", cube(Point3::new(10.0, 5.0, 0.0), Point3::new(50.0, 25.0, 8.0))));
